column4:
# All information on entities of type LearningResource in the Knowledge Hub

PREFIX n4e: <http://nfdi4earth.de/ontology/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX schema: <http://schema.org/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

CONSTRUCT {
  ?resource ?predicate ?object .
  ?object ?otherPredicate ?otherObject  .
}
WHERE {
  ?resource a schema:LearningResource .
  ?resource ?predicate ?object .
  OPTIONAL {
    ?resource schema:publisher ?object .
    BIND(foaf:name as ?otherPredicate) .
    ?object ?otherPredicate ?otherObject
  }
  OPTIONAL {
    ?resource schema:about ?object .
    BIND(dct:title as ?otherPredicate) .
    ?object dct:title ?object2
  }
  OPTIONAL {
    ?resource schema:license ?object .
    BIND(<http://spdx.org/rdf/terms#licenseId>  as ?otherPredicate) .
      ?object ?otherPredicate ?otherObject
  }
  OPTIONAL {
    ?resource <https://nfdi.fiz-karlsruhe.de/ontology/subjectArea> ?object .
    BIND(rdfs:label as ?otherPredicate) .
    ?object rdfs:label ?otherObject
  }
}

# All entities of type (NFDI4Earth) Aggregator (along with their title)
PREFIX n4e: <http://nfdi4earth.de/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core>

SELECT *
WHERE {
  ?subject rdf:type n4e:Aggregator;
  		   dct:title ?title.
}

PREFIX schema: <http://schema.org/>
PREFIX n4e: <http://nfdi4earth.de/ontology/>
prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT *
WHERE {
  {?subject rdf:type schema:LHBArticle ;
  			schema:name ?articleName}

 UNION { ?subject rdf:type n4e:Publication;
  			schema:name ?articleName}
 }

# Query for all datasets, that have 'world settlement footprint' in title or description
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX sc: <http://schema.org/>

SELECT ?s ?value ?license ?resourceUrl
WHERE {
    ?s rdf:type dcat:Dataset.
    {
        ?s dct:title ?value.
    }
    UNION
    {
        ?s dct:description ?value.
    }
    ?s sc:license ?license .
    ?s dcat:landingPage ?resourceUrl.
    FILTER (CONTAINS(LCASE(STR(?value)), "world settlement footprint"))
}

# All entities of type (NFDI4Earth) LHBArticle (along with their name and audience)

PREFIX n4e: <http://nfdi4earth.de/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX schema: <http://schema.org/>

SELECT *
WHERE {
  ?subject rdf:type n4e:LHBArticle;
   			schema:name ?name; 
      		schema:audience ?audience.
}

# All entities of type (schema) LearningResource (along with the learning type, if available)
PREFIX n4e: <http://nfdi4earth.de/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX schema: <http://schema.org/>

SELECT *
WHERE {
  ?subject rdf:type schema:LearningResource; 
           schema:name ?name.
           OPTIONAL{ ?subject schema:educationLevel ?educLevel}
         OPTIONAL{?subject schema:learningResourceType ?learningType}
}

# All entities of type (NFDI4Earth) MetadataStandard (along with their title and description)
PREFIX n4e: <http://nfdi4earth.de/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX dct: <http://purl.org/dc/terms/>

SELECT *
WHERE {
  ?subject rdf:type n4e:MetadataStandard ;
  		   dct:title ?title; 
       	   schema:description ?description
}

# All organizations in the NFDI4Earth Knowledge Graph, along with their names and URLs, if available
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX schema: <http://schema.org/>

SELECT *
WHERE {
  ?entity a foaf:Organization;
          schema:name ?name .
  OPTIONAL {?entity foaf:homepage ?homepage.}
}

# All entities of type (schema) Person (along with their names and affiliations, if available)
PREFIX n4e: <http://nfdi4earth.de/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX schema: <http://schema.org/>

SELECT ?name ?affil ?entity
WHERE {
  ?entity rdf:type schema:Person;
           schema:name ?name .
           OPTIONAL{?entity schema:affiliation ?affil}
}

# All types of n4e:Publication along with their names

PREFIX schema: <http://schema.org/>
PREFIX n4e: <http://nfdi4earth.de/ontology/>
prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT *
WHERE {
  ?subject rdf:type n4e:Publication;
  			schema:name ?publicationName
}

# All attributes available for the type Publication
PREFIX n4e: <http://nfdi4earth.de/ontology/>

SELECT DISTINCT ?predicate
WHERE {
  ?entity rdf:type n4e:Publication;
          ?predicate ?attributeInformation.
      FILTER(?predicate != rdf:type)
}

# Number of attributes available for the type Publication
# This tells us how many unary-attribute questions we can ask about the entity

PREFIX n4e: <http://nfdi4earth.de/ontology/>

SELECT (COUNT (DISTINCT ?predicate) as ?count )
WHERE {
  ?entity rdf:type n4e:Publication;
          ?predicate ?attributeInformation.
      FILTER(?predicate != rdf:type)
}

# All entities of type (NFDI4Earth) Registry, along with their title 
PREFIX n4e: <http://nfdi4earth.de/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core>

SELECT *
WHERE {
  ?subject rdf:type n4e:Registry ;
  		     dct:title ?title.
}

# All entities of type (NFDI4Earth) Repository, along with their title
PREFIX n4e: <http://nfdi4earth.de/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core>

SELECT *
WHERE {
  ?subject rdf:type n4e:Repository ;
  		     dct:title ?title.
}

# All entities of type (schema) ResearchProject (along with their names)

PREFIX n4e: <http://nfdi4earth.de/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX schema: <http://schema.org/>

SELECT *
WHERE {
  ?entity rdf:type schema:ResearchProject; 
		  schema:name ?name.
}

# All entities of type (schema) Software (along with their names and URL)

PREFIX n4e: <http://nfdi4earth.de/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX schema: <http://schema.org/>

SELECT *
WHERE {
  ?entity rdf:type n4e:Software; 
		  schema:name ?name;
    	  schema:codeRepository ?codeUrl.
}
